import random
import time

def solve_graceful_backtrack():
    n_vertices = 21
    n_edges = 39
    max_label = 39

    # Build edge list
    edge_list = []
    for g in range(7):
        base = 3 * g
        edge_list.append((base, base + 1))
        edge_list.append((base, base + 2))
        edge_list.append((base + 1, base + 2))
    for g in range(6):
        for i in range(3):
            u = 3 * g + i
            w = 3 * (g + 1) + i
            edge_list.append((u, w))

    # Build adjacency
    adj = [[] for _ in range(n_vertices)]
    for u, w in edge_list:
        adj[u].append(w)
        adj[w].append(u)

    start_time = time.time()
    timeout = 55

    labels = [-1] * n_vertices
    used_labels = [False] * (max_label + 1)
    used_edge_diffs = [False] * (max_label + 1)

    def get_new_diffs(v_idx, label):
        diffs = []
        for neighbor in adj[v_idx]:
            if labels[neighbor] != -1:
                diffs.append(abs(label - labels[neighbor]))
        return diffs

    def is_valid_assignment(v_idx, label):
        if used_labels[label]:
            return False
        for neighbor in adj[v_idx]:
            if labels[neighbor] != -1:
                diff = abs(label - labels[neighbor])
                if used_edge_diffs[diff]:
                    return False
        return True

    def assign(v_idx, label):
        labels[v_idx] = label
        used_labels[label] = True
        for neighbor in adj[v_idx]:
            if labels[neighbor] != -1:
                diff = abs(label - labels[neighbor])
                used_edge_diffs[diff] = True

    def unassign(v_idx, label):
        labels[v_idx] = -1
        used_labels[label] = False
        for neighbor in adj[v_idx]:
            if labels[neighbor] != -1:
                diff = abs(label - labels[neighbor])
                used_edge_diffs[diff] = False

    def count_remaining_valid_labels(v_idx):
        count = 0
        for l in range(max_label + 1):
            if is_valid_assignment(v_idx, l):
                count += 1
        return count

    def backtrack(idx):
        if time.time() - start_time > timeout:
            return None

        if idx == n_vertices:
            return labels[:]

        best_v = -1
        best_count = float('inf')
        for v in range(n_vertices):
            if labels[v] == -1:
                count = count_remaining_valid_labels(v)
                if count < best_count:
                    best_count = count
                    best_v = v
                if count == 0:
                    return None

        v_idx = best_v

        candidates = []
        for l in range(max_label + 1):
            if is_valid_assignment(v_idx, l):
                diffs = get_new_diffs(v_idx, l)
                candidates.append((len(diffs), l))

        candidates.sort(reverse=True)

        for _, label in candidates:
            assign(v_idx, label)
            result = backtrack(idx + 1)
            if result is not None:
                return result
            unassign(v_idx, label)

        return None

    result = backtrack(0)
    if result is not None:
        print(f"Found solution!")
        return result

    return None

result = solve_graceful_backtrack()
if result:
    print(f"Solution: {result}")
else:
    print("No solution found")
